<script setup lang="ts">
import { reactive, ref } from 'vue'
useSeoPage('Create account', 'Create a 247URL account to manage links, QR codes, and analytics.', '/register')
const { register }=useAuth(); const form=reactive({name:'',email:'',password:'',password_confirmation:''}); const errors=ref<Record<string,string[]>>({}); const loading=ref(false)
async function submit(){loading.value=true;errors.value={};try{await register(form);await navigateTo('/verify-email')}catch(e:any){errors.value=e?.data?.errors||{form:[e?.data?.message||'Unable to create your account.']}}finally{loading.value=false}}
</script>
<template><AuthShell title="Create your account" description="Start organizing links in a secure workspace."><form class="grid gap-4" @submit.prevent="submit"><div><label class="label" for="name">Full name</label><input id="name" v-model="form.name" class="input" autocomplete="name" required><p class="field-error">{{ errors.name?.[0] }}</p></div><div><label class="label" for="email">Email address</label><input id="email" v-model="form.email" class="input" type="email" autocomplete="email" required><p class="field-error">{{ errors.email?.[0] }}</p></div><div><label class="label" for="password">Password</label><input id="password" v-model="form.password" class="input" type="password" autocomplete="new-password" required><p class="mt-1 text-[11px] text-text-muted">12+ characters with upper, lower, number, and symbol.</p></div><div><label class="label" for="password-confirmation">Confirm password</label><input id="password-confirmation" v-model="form.password_confirmation" class="input" type="password" autocomplete="new-password" required><p class="field-error">{{ errors.password?.[0] || errors.form?.[0] }}</p></div><button class="btn-primary mt-1 w-full" :disabled="loading">{{ loading ? 'Creating account…' : 'Create account' }}</button></form><SocialAuthOptions/><p class="mt-5 text-center text-sm text-text-secondary">Already have an account? <NuxtLink to="/login" class="font-medium text-brand">Sign in</NuxtLink></p></AuthShell></template>
